const pptxgen = require("pptxgenjs");
const React = require("react");
const ReactDOMServer = require("react-dom/server");
const sharp = require("sharp");

// Icon imports
const { FaUserFriends, FaComments, FaPray, FaPills, FaExclamationTriangle, FaLock, FaSearchMinus, FaHospital } = require("react-icons/fa");
const { MdPsychology, MdHealthAndSafety } = require("react-icons/md");
const { HiUserGroup } = require("react-icons/hi");
const { BiBrain } = require("react-icons/bi");

function renderIconSvg(IconComponent, color = "#000000", size = 256) {
  return ReactDOMServer.renderToStaticMarkup(
    React.createElement(IconComponent, { color, size: String(size) })
  );
}

async function iconToBase64Png(IconComponent, color, size = 256) {
  const svg = renderIconSvg(IconComponent, color, size);
  const pngBuffer = await sharp(Buffer.from(svg)).png().toBuffer();
  return "image/png;base64," + pngBuffer.toString("base64");
}

// Color palette — Teal Trust + mental health appropriate
const C = {
  darkBg: "0B2027",
  teal: "028090",
  tealLight: "00A896",
  mint: "02C39A",
  white: "FFFFFF",
  offWhite: "F0F7F4",
  lightGray: "E8EFED",
  textDark: "1A2E35",
  textMid: "3D5A68",
  textLight: "6B8A97",
  accent: "F77F00",
  accentSoft: "FFF1E0",
  depression: "028090",
  anxiety: "00A896",
  schizo: "4A7C88",
  bipolar: "7FB3BE",
  eating: "B5D5DB",
  barBg: "E0EEEF",
};

const FONT_HEAD = "Georgia";
const FONT_BODY = "Calibri";

const makeShadow = () => ({ type: "outer", color: "000000", blur: 8, offset: 3, angle: 135, opacity: 0.12 });

async function main() {
  let pres = new pptxgen();
  pres.layout = "LAYOUT_16x9";
  pres.author = "Public Health Analytics";
  pres.title = "The Global Burden of Mental Illness: Prevalence, Impact, and the Treatment Gap";

  // ===== SLIDE 1: Title =====
  {
    let s = pres.addSlide();
    s.background = { color: C.darkBg };
    // Decorative shapes
    s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 0.15, h: 5.625, fill: { color: C.teal } });
    s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 4.4, w: 10, h: 0.06, fill: { color: C.tealLight, transparency: 40 } });

    s.addText("The Global Burden\nof Mental Illness", {
      x: 0.8, y: 0.8, w: 8.5, h: 2.2,
      fontSize: 42, fontFace: FONT_HEAD, color: C.white, bold: true,
      lineSpacingMultiple: 1.1, margin: 0,
    });
    s.addText("Prevalence, Impact, and the Treatment Gap", {
      x: 0.8, y: 3.0, w: 8.5, h: 0.6,
      fontSize: 20, fontFace: FONT_BODY, color: C.tealLight, margin: 0,
    });
    s.addText("Global Data, 2023  |  Source: Our World in Data / IHME, Global Burden of Disease (2025)", {
      x: 0.8, y: 4.7, w: 8.5, h: 0.4,
      fontSize: 11, fontFace: FONT_BODY, color: C.textLight, margin: 0,
    });
  }

  // ===== SLIDE 2: Prevalence / Scale =====
  {
    let s = pres.addSlide();
    s.background = { color: C.offWhite };
    s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.08, fill: { color: C.teal } });

    s.addText("Hundreds of Millions Affected", {
      x: 0.7, y: 0.35, w: 8.6, h: 0.55,
      fontSize: 28, fontFace: FONT_HEAD, color: C.textDark, bold: true, margin: 0,
    });
    s.addText("Lifetime risk of major depression", {
      x: 0.7, y: 0.9, w: 8.6, h: 0.35,
      fontSize: 14, fontFace: FONT_BODY, color: C.textMid, margin: 0,
    });

    // Large callout cards
    // Women card
    s.addShape(pres.shapes.RECTANGLE, {
      x: 0.7, y: 1.55, w: 4.0, h: 2.4, fill: { color: C.white },
      shadow: makeShadow(),
    });
    s.addShape(pres.shapes.RECTANGLE, { x: 0.7, y: 1.55, w: 4.0, h: 0.08, fill: { color: C.teal } });
    s.addText("1 in 3", {
      x: 0.7, y: 1.8, w: 4.0, h: 1.1,
      fontSize: 56, fontFace: FONT_HEAD, color: C.teal, bold: true, align: "center", valign: "middle", margin: 0,
    });
    s.addText("WOMEN", {
      x: 0.7, y: 2.85, w: 4.0, h: 0.5,
      fontSize: 18, fontFace: FONT_BODY, color: C.textDark, bold: true, align: "center", charSpacing: 4, margin: 0,
    });
    s.addText("will experience major depression\nin their lifetime", {
      x: 0.7, y: 3.3, w: 4.0, h: 0.55,
      fontSize: 12, fontFace: FONT_BODY, color: C.textMid, align: "center", margin: 0,
    });

    // Men card
    s.addShape(pres.shapes.RECTANGLE, {
      x: 5.3, y: 1.55, w: 4.0, h: 2.4, fill: { color: C.white },
      shadow: makeShadow(),
    });
    s.addShape(pres.shapes.RECTANGLE, { x: 5.3, y: 1.55, w: 4.0, h: 0.08, fill: { color: C.tealLight } });
    s.addText("1 in 5", {
      x: 5.3, y: 1.8, w: 4.0, h: 1.1,
      fontSize: 56, fontFace: FONT_HEAD, color: C.tealLight, bold: true, align: "center", valign: "middle", margin: 0,
    });
    s.addText("MEN", {
      x: 5.3, y: 2.85, w: 4.0, h: 0.5,
      fontSize: 18, fontFace: FONT_BODY, color: C.textDark, bold: true, align: "center", charSpacing: 4, margin: 0,
    });
    s.addText("will experience major depression\nin their lifetime", {
      x: 5.3, y: 3.3, w: 4.0, h: 0.55,
      fontSize: 12, fontFace: FONT_BODY, color: C.textMid, align: "center", margin: 0,
    });

    // Bottom context text
    s.addText("Mental health conditions range from common disorders like depression and anxiety to less common but severe conditions such as schizophrenia and bipolar disorder. All carry significant individual and societal costs.", {
      x: 0.7, y: 4.3, w: 8.6, h: 0.9,
      fontSize: 12, fontFace: FONT_BODY, color: C.textMid, margin: 0,
    });
  }

  // ===== SLIDE 3: Burden by Category — Horizontal Bar Chart =====
  {
    let s = pres.addSlide();
    s.background = { color: C.offWhite };
    s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.08, fill: { color: C.teal } });

    s.addText("Disease Burden by Mental Illness Category", {
      x: 0.7, y: 0.3, w: 8.6, h: 0.55,
      fontSize: 26, fontFace: FONT_HEAD, color: C.textDark, bold: true, margin: 0,
    });
    s.addText("DALYs per 100,000 people  |  World, 2023", {
      x: 0.7, y: 0.85, w: 8.6, h: 0.3,
      fontSize: 12, fontFace: FONT_BODY, color: C.textMid, margin: 0,
    });

    s.addChart(pres.charts.BAR, [{
      name: "DALYs per 100K",
      labels: ["Eating Disorders", "Bipolar Disorder", "Schizophrenia", "Anxiety Disorders", "Depressive Disorders"],
      values: [47.5, 94.6, 210.2, 686.5, 694.6],
    }], {
      x: 0.7, y: 1.35, w: 8.6, h: 3.6,
      barDir: "bar",
      barGrouping: "clustered",
      chartColors: [C.teal],
      chartArea: { fill: { color: C.offWhite }, roundedCorners: false },
      plotArea: { fill: { color: C.offWhite } },
      catAxisLabelColor: C.textDark,
      catAxisLabelFontSize: 12,
      catAxisLabelFontFace: FONT_BODY,
      valAxisLabelColor: C.textLight,
      valAxisLabelFontSize: 10,
      valGridLine: { color: "D0DDDF", size: 0.5 },
      catGridLine: { style: "none" },
      showValue: true,
      dataLabelPosition: "outEnd",
      dataLabelColor: C.textDark,
      dataLabelFontSize: 11,
      dataLabelFontFace: FONT_BODY,
      showLegend: false,
    });

    s.addText("Source: IHME, Global Burden of Disease (2025) via Our World in Data", {
      x: 0.7, y: 5.1, w: 8.6, h: 0.3,
      fontSize: 9, fontFace: FONT_BODY, color: C.textLight, margin: 0,
    });
  }

  // ===== SLIDE 4: Depression vs Anxiety Parity =====
  {
    let s = pres.addSlide();
    s.background = { color: C.offWhite };
    s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.08, fill: { color: C.teal } });

    s.addText("Depression and Anxiety Carry Nearly Equal Burden", {
      x: 0.7, y: 0.3, w: 8.6, h: 0.55,
      fontSize: 26, fontFace: FONT_HEAD, color: C.textDark, bold: true, margin: 0,
    });
    s.addText("Together they account for roughly 80% of the total mental health disease burden", {
      x: 0.7, y: 0.85, w: 8.6, h: 0.3,
      fontSize: 13, fontFace: FONT_BODY, color: C.textMid, margin: 0,
    });

    // Paired bars — side by side comparison
    s.addChart(pres.charts.BAR, [
      {
        name: "Depressive Disorders",
        labels: ["Disease Burden (DALYs per 100K)"],
        values: [694.6],
      },
      {
        name: "Anxiety Disorders",
        labels: ["Disease Burden (DALYs per 100K)"],
        values: [686.5],
      },
    ], {
      x: 0.7, y: 1.4, w: 8.6, h: 2.6,
      barDir: "bar",
      barGrouping: "clustered",
      chartColors: [C.teal, C.tealLight],
      chartArea: { fill: { color: C.offWhite }, roundedCorners: false },
      plotArea: { fill: { color: C.offWhite } },
      catAxisLabelColor: C.textDark,
      catAxisLabelFontSize: 12,
      catAxisLabelFontFace: FONT_BODY,
      valAxisLabelColor: C.textLight,
      valAxisLabelFontSize: 10,
      valGridLine: { color: "D0DDDF", size: 0.5 },
      catGridLine: { style: "none" },
      showValue: true,
      dataLabelPosition: "outEnd",
      dataLabelColor: C.textDark,
      dataLabelFontSize: 12,
      dataLabelFontFace: FONT_BODY,
      showLegend: true,
      legendPos: "b",
      legendFontSize: 11,
      legendColor: C.textDark,
    });

    // Callout box
    s.addShape(pres.shapes.RECTANGLE, {
      x: 0.7, y: 4.3, w: 8.6, h: 0.9,
      fill: { color: C.white }, shadow: makeShadow(),
    });
    s.addShape(pres.shapes.RECTANGLE, { x: 0.7, y: 4.3, w: 0.08, h: 0.9, fill: { color: C.accent } });
    s.addText("Combined, depressive and anxiety disorders generate ~1,381 DALYs per 100,000 — dwarfing schizophrenia, bipolar disorder, and eating disorders combined (352 DALYs per 100K).", {
      x: 1.0, y: 4.3, w: 8.1, h: 0.9,
      fontSize: 12, fontFace: FONT_BODY, color: C.textDark, valign: "middle", margin: 0,
    });
  }

  // ===== SLIDE 5: Severe Conditions =====
  {
    let s = pres.addSlide();
    s.background = { color: C.offWhite };
    s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.08, fill: { color: C.teal } });

    s.addText("Lower Prevalence, Severe Individual Impact", {
      x: 0.7, y: 0.3, w: 8.6, h: 0.55,
      fontSize: 26, fontFace: FONT_HEAD, color: C.textDark, bold: true, margin: 0,
    });
    s.addText("Schizophrenia and Bipolar Disorder vs. Common Disorders", {
      x: 0.7, y: 0.85, w: 8.6, h: 0.3,
      fontSize: 13, fontFace: FONT_BODY, color: C.textMid, margin: 0,
    });

    // Proportional visual — stacked bar showing relative share
    s.addChart(pres.charts.BAR, [{
      name: "DALYs per 100K",
      labels: ["Depressive\nDisorders", "Anxiety\nDisorders", "Schizophrenia", "Bipolar\nDisorder", "Eating\nDisorders"],
      values: [694.6, 686.5, 210.2, 94.6, 47.5],
    }], {
      x: 0.7, y: 1.35, w: 8.6, h: 2.5,
      barDir: "col",
      barGrouping: "clustered",
      chartColors: [C.teal],
      chartArea: { fill: { color: C.offWhite }, roundedCorners: false },
      plotArea: { fill: { color: C.offWhite } },
      catAxisLabelColor: C.textDark,
      catAxisLabelFontSize: 10,
      catAxisLabelFontFace: FONT_BODY,
      valAxisLabelColor: C.textLight,
      valAxisLabelFontSize: 10,
      valGridLine: { color: "D0DDDF", size: 0.5 },
      catGridLine: { style: "none" },
      showValue: true,
      dataLabelPosition: "outEnd",
      dataLabelColor: C.textDark,
      dataLabelFontSize: 10,
      dataLabelFontFace: FONT_BODY,
      showLegend: false,
    });

    // Two callout cards at bottom
    s.addShape(pres.shapes.RECTANGLE, {
      x: 0.7, y: 4.15, w: 4.0, h: 1.1, fill: { color: C.white }, shadow: makeShadow(),
    });
    s.addShape(pres.shapes.RECTANGLE, { x: 0.7, y: 4.15, w: 0.08, h: 1.1, fill: { color: C.schizo } });
    s.addText([
      { text: "Schizophrenia: 210.2 DALYs", options: { bold: true, fontSize: 13, breakLine: true } },
      { text: "Affects fewer people, but causes severe disability — reflecting the intense individual burden.", options: { fontSize: 11 } },
    ], {
      x: 1.0, y: 4.2, w: 3.5, h: 1.0,
      fontFace: FONT_BODY, color: C.textDark, valign: "middle", margin: 0,
    });

    s.addShape(pres.shapes.RECTANGLE, {
      x: 5.3, y: 4.15, w: 4.0, h: 1.1, fill: { color: C.white }, shadow: makeShadow(),
    });
    s.addShape(pres.shapes.RECTANGLE, { x: 5.3, y: 4.15, w: 0.08, h: 1.1, fill: { color: C.bipolar } });
    s.addText([
      { text: "Bipolar Disorder: 94.6 DALYs", options: { bold: true, fontSize: 13, breakLine: true } },
      { text: "A smaller population burden, yet meaningful — individuals face recurrent and disruptive episodes.", options: { fontSize: 11 } },
    ], {
      x: 5.6, y: 4.2, w: 3.5, h: 1.0,
      fontFace: FONT_BODY, color: C.textDark, valign: "middle", margin: 0,
    });
  }

  // ===== SLIDE 6: Treatment Gap =====
  {
    let s = pres.addSlide();
    s.background = { color: C.offWhite };
    s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.08, fill: { color: C.teal } });

    s.addText("The Treatment Gap", {
      x: 0.7, y: 0.3, w: 8.6, h: 0.55,
      fontSize: 28, fontFace: FONT_HEAD, color: C.textDark, bold: true, margin: 0,
    });
    s.addText("Mental illnesses are treatable — yet many people do not receive adequate care", {
      x: 0.7, y: 0.85, w: 8.6, h: 0.3,
      fontSize: 13, fontFace: FONT_BODY, color: C.textMid, margin: 0,
    });

    const iconStigma = await iconToBase64Png(FaLock, "#028090", 256);
    const iconAccess = await iconToBase64Png(FaHospital, "#028090", 256);
    const iconQuality = await iconToBase64Png(FaExclamationTriangle, "#028090", 256);
    const iconData = await iconToBase64Png(FaSearchMinus, "#028090", 256);

    const barriers = [
      { icon: iconStigma, title: "Stigma", desc: "Many people are uncomfortable disclosing symptoms to healthcare professionals or even people they know." },
      { icon: iconAccess, title: "Access", desc: "Treatment is often lacking, especially in low- and middle-income countries." },
      { icon: iconQuality, title: "Quality", desc: "Even where treatment exists, it may be of poor quality and insufficient to meet patient needs." },
      { icon: iconData, title: "Underreporting", desc: "Discomfort with disclosure makes it difficult to estimate true prevalence — the actual burden may be higher than reported." },
    ];

    barriers.forEach((b, i) => {
      const yBase = 1.5 + i * 0.95;
      // Card background
      s.addShape(pres.shapes.RECTANGLE, {
        x: 0.7, y: yBase, w: 8.6, h: 0.82,
        fill: { color: C.white }, shadow: makeShadow(),
      });
      // Icon circle
      s.addShape(pres.shapes.OVAL, {
        x: 1.0, y: yBase + 0.13, w: 0.56, h: 0.56,
        fill: { color: C.barBg },
      });
      s.addImage({ data: b.icon, x: 1.1, y: yBase + 0.23, w: 0.36, h: 0.36 });
      // Title
      s.addText(b.title, {
        x: 1.8, y: yBase + 0.05, w: 7.2, h: 0.32,
        fontSize: 14, fontFace: FONT_BODY, color: C.textDark, bold: true, valign: "middle", margin: 0,
      });
      // Description
      s.addText(b.desc, {
        x: 1.8, y: yBase + 0.38, w: 7.2, h: 0.38,
        fontSize: 11, fontFace: FONT_BODY, color: C.textMid, valign: "top", margin: 0,
      });
    });

    s.addText("Good data is essential to understand these conditions — how, when, and why they occur, and how they can be treated effectively.", {
      x: 0.7, y: 5.1, w: 8.6, h: 0.35,
      fontSize: 10, fontFace: FONT_BODY, color: C.textLight, italic: true, margin: 0,
    });
  }

  // ===== SLIDE 7: Coping Strategies =====
  {
    let s = pres.addSlide();
    s.background = { color: C.offWhite };
    s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.08, fill: { color: C.teal } });

    s.addText("How People Cope with Mental Health Conditions", {
      x: 0.7, y: 0.3, w: 8.6, h: 0.55,
      fontSize: 26, fontFace: FONT_HEAD, color: C.textDark, bold: true, margin: 0,
    });
    s.addText("Global survey data reveals wide variation across countries and cultures", {
      x: 0.7, y: 0.85, w: 8.6, h: 0.3,
      fontSize: 13, fontFace: FONT_BODY, color: C.textMid, margin: 0,
    });

    const iconMed = await iconToBase64Png(FaPills, "#028090", 256);
    const iconFaith = await iconToBase64Png(FaPray, "#00A896", 256);
    const iconTalk = await iconToBase64Png(FaComments, "#02C39A", 256);

    const strategies = [
      {
        icon: iconMed, color: C.teal,
        title: "Prescribed Medication",
        desc: "Common in higher-income settings where pharmaceutical access and healthcare infrastructure are established.",
      },
      {
        icon: iconFaith, color: C.tealLight,
        title: "Religious or Spiritual Activities",
        desc: "Prevalent in many regions worldwide, reflecting deep cultural and communal support frameworks.",
      },
      {
        icon: iconTalk, color: C.mint,
        title: "Talking to Friends or Family",
        desc: "A widely reported coping mechanism across diverse demographics and income levels.",
      },
    ];

    strategies.forEach((st, i) => {
      const yBase = 1.5 + i * 1.2;
      // Card
      s.addShape(pres.shapes.RECTANGLE, {
        x: 0.7, y: yBase, w: 8.6, h: 1.0,
        fill: { color: C.white }, shadow: makeShadow(),
      });
      s.addShape(pres.shapes.RECTANGLE, { x: 0.7, y: yBase, w: 0.08, h: 1.0, fill: { color: st.color } });
      // Icon circle
      s.addShape(pres.shapes.OVAL, {
        x: 1.1, y: yBase + 0.2, w: 0.6, h: 0.6,
        fill: { color: C.barBg },
      });
      s.addImage({ data: st.icon, x: 1.22, y: yBase + 0.32, w: 0.36, h: 0.36 });
      // Title
      s.addText(st.title, {
        x: 2.0, y: yBase + 0.12, w: 7.0, h: 0.35,
        fontSize: 15, fontFace: FONT_BODY, color: C.textDark, bold: true, valign: "middle", margin: 0,
      });
      // Desc
      s.addText(st.desc, {
        x: 2.0, y: yBase + 0.5, w: 7.0, h: 0.4,
        fontSize: 11.5, fontFace: FONT_BODY, color: C.textMid, valign: "top", margin: 0,
      });
    });

    // Bottom insight
    s.addShape(pres.shapes.RECTANGLE, {
      x: 0.7, y: 5.0, w: 8.6, h: 0.45,
      fill: { color: C.accentSoft },
    });
    s.addShape(pres.shapes.RECTANGLE, { x: 0.7, y: 5.0, w: 0.08, h: 0.45, fill: { color: C.accent } });
    s.addText("Policy interventions must account for cultural, economic, and healthcare system differences — not apply a one-size-fits-all approach.", {
      x: 1.0, y: 5.0, w: 8.1, h: 0.45,
      fontSize: 11, fontFace: FONT_BODY, color: C.textDark, bold: true, valign: "middle", margin: 0,
    });
  }

  // ===== SLIDE 8: Key Takeaways =====
  {
    let s = pres.addSlide();
    s.background = { color: C.darkBg };
    s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 0.15, h: 5.625, fill: { color: C.teal } });

    s.addText("Key Takeaways", {
      x: 0.7, y: 0.35, w: 8.6, h: 0.6,
      fontSize: 32, fontFace: FONT_HEAD, color: C.white, bold: true, margin: 0,
    });
    s.addText("Priorities for Policy Analysts and Program Planners", {
      x: 0.7, y: 0.95, w: 8.6, h: 0.35,
      fontSize: 14, fontFace: FONT_BODY, color: C.tealLight, margin: 0,
    });

    const takeaways = [
      { num: "1", text: "Depression and anxiety together represent the overwhelming majority of mental health DALYs — roughly 80% of the combined burden across five categories." },
      { num: "2", text: "Schizophrenia and bipolar disorder carry disproportionate individual burden despite lower population-level prevalence." },
      { num: "3", text: "Effective treatments exist but access and quality remain inadequate, particularly in low- and middle-income countries." },
      { num: "4", text: "Stigma suppresses both help-seeking and accurate data, meaning the true burden of mental illness is likely underestimated." },
      { num: "5", text: "Policy should prioritize scaling evidence-based interventions for common disorders while maintaining specialized care for severe conditions." },
    ];

    takeaways.forEach((t, i) => {
      const yBase = 1.55 + i * 0.75;
      // Number circle
      s.addShape(pres.shapes.OVAL, {
        x: 0.7, y: yBase + 0.05, w: 0.42, h: 0.42,
        fill: { color: C.teal },
      });
      s.addText(t.num, {
        x: 0.7, y: yBase + 0.05, w: 0.42, h: 0.42,
        fontSize: 14, fontFace: FONT_BODY, color: C.white, bold: true, align: "center", valign: "middle", margin: 0,
      });
      // Text
      s.addText(t.text, {
        x: 1.3, y: yBase, w: 8.0, h: 0.6,
        fontSize: 12.5, fontFace: FONT_BODY, color: C.white, valign: "middle", margin: 0,
      });
    });

    s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 5.2, w: 10, h: 0.06, fill: { color: C.tealLight, transparency: 40 } });
    s.addText("Data: IHME, Global Burden of Disease (2025) | Presentation: Our World in Data", {
      x: 0.7, y: 5.25, w: 8.6, h: 0.3,
      fontSize: 9, fontFace: FONT_BODY, color: C.textLight, margin: 0,
    });
  }

  await pres.writeFile({ fileName: "/app/output/final_deck.pptx" });
  console.log("Presentation saved to /app/output/final_deck.pptx");
}

main().catch(err => { console.error(err); process.exit(1); });

