const pptxgen = require("pptxgenjs");
const React = require("react");
const ReactDOMServer = require("react-dom/server");
const sharp = require("sharp");

// Icon imports
const { FaUserFriends, FaComments, FaPray, FaPills, FaExclamationTriangle, FaLock, FaSearchMinus, FaHospital } = require("react-icons/fa");
const { MdPsychology, MdHealthAndSafety } = require("react-icons/md");
const { HiUserGroup } = require("react-icons/hi");
const { BiBrain } = require("react-icons/bi");

function renderIconSvg(IconComponent, color = "#000000", size = 256) {
  return ReactDOMServer.renderToStaticMarkup(
    React.createElement(IconComponent, { color, size: String(size) })
  );
}

async function iconToBase64Png(IconComponent, color, size = 256) {
  const svg = renderIconSvg(IconComponent, color, size);
  const pngBuffer = await sharp(Buffer.from(svg)).png().toBuffer();
  return "image/png;base64," + pngBuffer.toString("base64");
}

// Color palette — Teal Trust + mental health appropriate
const C = {
  darkBg: "0B2027",
  teal: "028090",
  tealLight: "00A896",
  mint: "02C39A",
  white: "FFFFFF",
  offWhite: "F0F7F4",
  lightGray: "E8EFED",
  textDark: "1A2E35",
  textMid: "3D5A68",
  textLight: "6B8A97",
  accent: "F77F00",
  accentSoft: "FFF1E0",
  depression: "028090",
  anxiety: "00A896",
  schizo: "4A7C88",
  bipolar: "7FB3BE",
  eating: "B5D5DB",
  barBg: "E0EEEF",
};

const FONT_HEAD = "Georgia";
const FONT_BODY = "Calibri";

const makeShadow = () => ({ type: "outer", color: "000000", blur: 8, offset: 3, angle: 135, opacity: 0.12 });

